-- 官方履歷政策；保留原 claim 與來源，不表示第三方內容錯誤。
-- 本機及發布使用同一檔；正式執行須另行授權。無人物／參選刪除。
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='10min';

CREATE OR REPLACE FUNCTION public.official_profile_claim_allowed(
 p_type text,p_value text,p_json jsonb,p_person uuid,p_url text)
RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $f$
 SELECT p_type NOT IN ('birth_date','education','experience') OR COALESCE(
 p_url ~* '^https?://(([a-z0-9-]+\.)*gov\.tw|academicians\.sinica\.edu\.tw)([/:?#]|$)'
 AND p_json->'officialProfilePolicy'->>'version'='official-profile-v1'
 AND p_json->'officialProfilePolicy'->>'eligible'='true'
 AND p_json->'officialProfilePolicy'->>'identityVerified'='true'
 AND p_json->'officialProfilePolicy'->>'contentVerified'='true'
 AND (p_type<>'birth_date' OR
  (CASE p_json->'officialProfilePolicy'->>'datePrecision'
    WHEN 'year' THEN p_value ~ '^(18|19|20|21)[0-9]{2}$'
    WHEN 'month' THEN p_value ~ '^(18|19|20|21)[0-9]{2}-(0[1-9]|1[0-2])$'
    WHEN 'day' THEN p_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND pg_input_is_valid(p_value,'date')
    ELSE false END))
 AND p_json->'officialProfilePolicy'->>'binding'=md5(p_person::text||'|'||p_type||'|'||COALESCE(p_value,p_json->>'value','')||'|'||COALESCE(p_url,'')),false);
$f$;

-- Preserve reviewed attestations only when the person, value and source still match.
CREATE OR REPLACE FUNCTION public.guard_official_profile_claim()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $f$
BEGIN
 IF NEW.claim_type NOT IN ('birth_date','education','experience') THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND public.official_profile_claim_allowed(OLD.claim_type,OLD.claim_value,OLD.claim_json,OLD.person_id,OLD.source_url)
   AND ROW(NEW.person_id,NEW.claim_type,NEW.claim_value,NEW.source_url) IS NOT DISTINCT FROM ROW(OLD.person_id,OLD.claim_type,OLD.claim_value,OLD.source_url)
   AND (NOT (COALESCE(NEW.claim_json,'{}'::jsonb) ? 'officialProfilePolicy')
    OR NEW.claim_json->'officialProfilePolicy'->>'reason' IN ('official_evidence_pending','official_identity_or_content_evidence_pending')) THEN
   NEW.claim_json:=COALESCE(NEW.claim_json,'{}'::jsonb)||jsonb_build_object('officialProfilePolicy',OLD.claim_json->'officialProfilePolicy');
   NEW.review_status:=OLD.review_status;NEW.visibility:=OLD.visibility;NEW.is_public:=OLD.is_public;
 END IF;
 -- Only the existing privileged review/migration boundary may create a new attestation.
 -- Imports may preserve an identical persisted attestation; supplied JSON is not authority.
 IF current_user NOT IN ('postgres','supabase_admin') AND
    (TG_OP='INSERT' OR NOT public.official_profile_claim_allowed(OLD.claim_type,OLD.claim_value,OLD.claim_json,OLD.person_id,OLD.source_url)
     OR ROW(NEW.person_id,NEW.claim_type,NEW.claim_value,NEW.source_url) IS DISTINCT FROM ROW(OLD.person_id,OLD.claim_type,OLD.claim_value,OLD.source_url)
     OR NEW.claim_json->'officialProfilePolicy' IS DISTINCT FROM OLD.claim_json->'officialProfilePolicy') THEN
   NEW.claim_json:=COALESCE(NEW.claim_json,'{}'::jsonb)-'officialProfilePolicy';
 END IF;
 IF NOT public.official_profile_claim_allowed(NEW.claim_type,NEW.claim_value,NEW.claim_json,NEW.person_id,NEW.source_url) THEN
   NEW.claim_json:=COALESCE(NEW.claim_json,'{}'::jsonb)||jsonb_build_object('officialProfilePolicy',
     COALESCE(NEW.claim_json->'officialProfilePolicy','{}'::jsonb)||jsonb_build_object(
      'version','official-profile-v1','eligible',false,'notAnErrorFinding',true,
      'reason',CASE WHEN NEW.source_url ~* '^https?://(([a-z0-9-]+\.)*gov\.tw|academicians\.sinica\.edu\.tw)([/:?#]|$)' THEN 'official_identity_or_content_evidence_pending' ELSE 'source_policy_disabled' END));
   IF NEW.review_status NOT IN ('rejected','archived') THEN
     NEW.review_status:=CASE WHEN NEW.source_url ~* '^https?://(([a-z0-9-]+\.)*gov\.tw|academicians\.sinica\.edu\.tw)([/:?#]|$)' THEN 'pending' ELSE 'archived' END;
   END IF;
   NEW.visibility:='private'; NEW.is_public:=false;
 END IF;
 RETURN NEW;
END $f$;
REVOKE ALL ON FUNCTION public.guard_official_profile_claim() FROM PUBLIC,anon,authenticated;

