DO $review_scope$ BEGIN
 IF EXISTS(SELECT 1 FROM public.person_claims c
  WHERE c.claim_type IN ('birth_date','education','experience') AND c.review_status='verified' AND c.visibility='public' AND c.is_public
   AND c.source_url ~* '^https?://(([a-z0-9-]+\.)*gov\.tw|academicians\.sinica\.edu\.tw)([/:?#]|$)'
   AND NOT public.official_profile_claim_allowed(c.claim_type,c.claim_value,c.claim_json,c.person_id,c.source_url)
   AND NOT EXISTS(SELECT 1 FROM official_profile_review_scope s WHERE s.id=c.id AND s.binding=md5(c.person_id::text||'|'||c.claim_type||'|'||COALESCE(c.claim_value,c.claim_json->>'value','')||'|'||COALESCE(c.source_url,''))))
 THEN RAISE EXCEPTION 'Official profile review baseline drift: reconcile this environment before applying source policy'; END IF;
END $review_scope$;

-- Existing reviewed official evidence. These bindings do not authorize changed values.
CREATE TEMP TABLE official_profile_attestations(id uuid PRIMARY KEY,person_id uuid,claim_type text,claim_value text,source_url text,policy jsonb) ON COMMIT DROP;
