UPDATE public.person_claims c SET claim_json=COALESCE(c.claim_json,'{}'::jsonb)||jsonb_build_object('officialProfilePolicy',a.policy)
FROM official_profile_attestations a
WHERE c.id=a.id AND c.person_id=a.person_id AND c.claim_type=a.claim_type AND c.claim_value IS NOT DISTINCT FROM a.claim_value AND c.source_url=a.source_url
 AND c.review_status='verified'
 AND c.claim_json->'officialProfilePolicy' IS DISTINCT FROM a.policy;

-- Archive policy-disabled evidence in place. Original value, ID, source, metadata remain.
UPDATE public.person_claims c SET
 claim_json=COALESCE(c.claim_json,'{}'::jsonb)||jsonb_build_object('officialProfilePolicy',
  jsonb_build_object('version','official-profile-v1','eligible',false,'notAnErrorFinding',true,
   'previousReviewStatus',c.review_status,'previousVisibility',c.visibility,'previousIsPublic',c.is_public,
   'reason',CASE WHEN c.source_url ~* '^https?://(([a-z0-9-]+\.)*gov\.tw|academicians\.sinica\.edu\.tw)([/:?#]|$)' THEN 'official_identity_or_content_evidence_pending' ELSE 'source_policy_disabled' END)),
 review_status=CASE WHEN c.review_status IN ('rejected','archived') THEN c.review_status
   WHEN c.source_url ~* '^https?://(([a-z0-9-]+\.)*gov\.tw|academicians\.sinica\.edu\.tw)([/:?#]|$)' THEN 'pending' ELSE 'archived' END,
 visibility='private',is_public=false
WHERE c.claim_type IN ('birth_date','education','experience')
 AND NOT public.official_profile_claim_allowed(c.claim_type,c.claim_value,c.claim_json,c.person_id,c.source_url)
 AND c.claim_json->'officialProfilePolicy'->>'version' IS DISTINCT FROM 'official-profile-v1';

DROP TRIGGER IF EXISTS guard_official_profile_claim ON public.person_claims;
CREATE TRIGGER guard_official_profile_claim BEFORE INSERT OR UPDATE ON public.person_claims
FOR EACH ROW EXECUTE FUNCTION public.guard_official_profile_claim();

CREATE OR REPLACE FUNCTION public.official_profile_raw_text(p_person uuid,p_type text)
RETURNS text LANGUAGE sql STABLE SET search_path='' AS $f$
 SELECT string_agg(DISTINCT NULLIF(btrim(c.claim_value),''),E'
' ORDER BY NULLIF(btrim(c.claim_value),''))
 FROM public.person_claims c WHERE c.person_id=p_person AND c.claim_type=p_type
 AND c.review_status='verified' AND c.visibility='public' AND c.is_public
 AND public.official_profile_claim_allowed(c.claim_type,c.claim_value,c.claim_json,c.person_id,c.source_url);
$f$;

REVOKE ALL ON FUNCTION public.official_profile_raw_text(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.official_profile_raw_text(uuid,text) TO service_role;

-- No unreviewed profile text can be restored by a people upsert.
CREATE OR REPLACE FUNCTION public.guard_official_people_fields()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $f$
BEGIN
 NEW.education:=public.official_profile_raw_text(NEW.id,'education');
 NEW.experience:=public.official_profile_raw_text(NEW.id,'experience');
 RETURN NEW;
END $f$;
REVOKE ALL ON FUNCTION public.guard_official_people_fields() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS guard_official_people_fields ON public.people;
CREATE TRIGGER guard_official_people_fields BEFORE INSERT OR UPDATE OF education,experience ON public.people
FOR EACH ROW EXECUTE FUNCTION public.guard_official_people_fields();

UPDATE public.people p SET education=public.official_profile_raw_text(p.id,'education'),
 experience=public.official_profile_raw_text(p.id,'experience')
WHERE ROW(p.education,p.experience) IS DISTINCT FROM ROW(public.official_profile_raw_text(p.id,'education'),public.official_profile_raw_text(p.id,'experience'));

CREATE OR REPLACE FUNCTION public.sync_official_people_fields()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE v_id uuid;
BEGIN
 IF TG_OP='INSERT' AND NEW.claim_type NOT IN ('birth_date','education','experience') THEN RETURN NULL; END IF;
 IF TG_OP='DELETE' AND OLD.claim_type NOT IN ('birth_date','education','experience') THEN RETURN NULL; END IF;
 IF TG_OP='UPDATE' AND NEW.claim_type NOT IN ('birth_date','education','experience') AND OLD.claim_type NOT IN ('birth_date','education','experience') THEN RETURN NULL; END IF;
 FOR v_id IN SELECT DISTINCT x FROM unnest(ARRAY[CASE WHEN TG_OP<>'INSERT' THEN OLD.person_id END,CASE WHEN TG_OP<>'DELETE' THEN NEW.person_id END]) x WHERE x IS NOT NULL LOOP
   UPDATE public.people p SET education=public.official_profile_raw_text(p.id,'education'),
    experience=public.official_profile_raw_text(p.id,'experience') WHERE p.id=v_id
    AND ROW(p.education,p.experience) IS DISTINCT FROM ROW(public.official_profile_raw_text(p.id,'education'),public.official_profile_raw_text(p.id,'experience'));
 END LOOP;
 RETURN NULL;
END $f$;
REVOKE ALL ON FUNCTION public.sync_official_people_fields() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS sync_official_people_fields ON public.person_claims;
CREATE TRIGGER sync_official_people_fields AFTER INSERT OR UPDATE OR DELETE ON public.person_claims
FOR EACH ROW
EXECUTE FUNCTION public.sync_official_people_fields();

CREATE OR REPLACE VIEW public.official_profile_values WITH (security_invoker=false) AS
WITH eligible AS (
 SELECT m.canonical_person_id person_id,c.claim_type,COALESCE(c.claim_value,c.claim_json->>'value') value,c.claim_json
 FROM public.person_claims c JOIN public.person_canonical_map m ON m.person_id=c.person_id
 WHERE c.claim_type IN ('birth_date','education','experience') AND c.review_status='verified'
 AND c.visibility='public' AND c.is_public
 AND public.official_profile_claim_allowed(c.claim_type,c.claim_value,c.claim_json,c.person_id,c.source_url)
), aggregated AS (
 SELECT person_id,
  string_agg(DISTINCT NULLIF(btrim(value),''),E'
' ORDER BY NULLIF(btrim(value),'')) FILTER(WHERE claim_type='education') education,
  string_agg(DISTINCT NULLIF(btrim(value),''),E'
' ORDER BY NULLIF(btrim(value),'')) FILTER(WHERE claim_type='experience') experience,
  array_agg(DISTINCT value) FILTER(WHERE claim_type='birth_date') dates
 FROM eligible GROUP BY person_id
)
SELECT person_id,education,experience,
 CASE WHEN NOT EXISTS(SELECT 1 FROM unnest(dates) a CROSS JOIN unnest(dates) b WHERE left(a,least(length(a),length(b)))<>left(b,least(length(a),length(b))))
 THEN (SELECT d FROM unnest(dates) d ORDER BY length(d) DESC,d LIMIT 1) END birth_value,
 EXISTS(SELECT 1 FROM unnest(dates) a CROSS JOIN unnest(dates) b WHERE left(a,least(length(a),length(b)))<>left(b,least(length(a),length(b)))) birth_conflict
FROM aggregated;
REVOKE ALL ON public.official_profile_values FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.official_profile_values TO service_role;

-- Preserve released office/status logic; only education/experience use official values.
CREATE OR REPLACE VIEW public.public_people AS
WITH mapped_people AS (
         SELECT canonical_map.canonical_person_id,
            person.id,
            person.name,
            person.alias,
            person.party,
            person."position",
            person.election_year,
            person.district,
            person.source_url,
            person.is_public,
            person.created_at,
            person.updated_at,
            person.external_id,
            person.gender,
            person.education,
            person.experience
           FROM people person
             JOIN person_canonical_map canonical_map ON canonical_map.person_id = person.id
          WHERE person.is_public = true
        ), canonical_people AS (
         SELECT person.id,
            person.name,
            person.alias,
            person.party,
            person."position",
            person.election_year,
            person.district,
            person.source_url,
            person.is_public,
            person.created_at,
            person.updated_at,
            person.external_id,
            person.gender,
            person.education,
            person.experience
           FROM people person
          WHERE person.is_public = true
        ), candidate_offices AS (
         SELECT person_map.canonical_person_id,
            candidate.id AS candidate_id,
            candidate.registration_status,
            candidate.candidacy_status,
            candidate.is_elected,
            candidate.updated_at,
            election.year AS election_year,
            race.race_type,
            NULLIF(btrim(regexp_replace(race.title, '候選人|選舉|全國'::text, ''::text, 'g'::text)), ''::text) AS race_label,
            NULLIF(btrim(regexp_replace(person."position", '候選人|選舉|全國'::text, ''::text, 'g'::text)), ''::text) AS person_position_label,
            race.title AS race_title,
            person."position" AS person_position
           FROM candidates candidate
             JOIN person_canonical_map person_map ON person_map.person_id = candidate.person_id
             JOIN race_canonical_map race_map ON race_map.race_id = candidate.race_id
             JOIN races race ON race.id = race_map.canonical_race_id AND race.is_public = true
             JOIN elections election ON election.id = race.election_id AND election.is_public = true
             JOIN people person ON person.id = person_map.canonical_person_id AND person.is_public = true
             LEFT JOIN regions region ON region.id = race.region_id
          WHERE candidate.is_public = true AND (race.region_id IS NULL OR region.is_public = true)
        ), ended_current_offices AS (
         SELECT person_map.canonical_person_id,
            exclusion.election_year,
            exclusion.race_type
           FROM current_office_exclusions exclusion
             JOIN person_canonical_map person_map ON person_map.person_id = exclusion.person_id
        ), current_offices AS (
         SELECT DISTINCT ON (candidate_offices.canonical_person_id) candidate_offices.canonical_person_id,
                CASE
                    WHEN candidate_offices.race_label ~~ '%總統%'::text AND candidate_offices.race_label ~~ '%副總統%'::text AND candidate_offices.person_position_label ~~ '%副總統%'::text THEN '副總統'::text
                    WHEN candidate_offices.race_label ~~ '%總統%'::text AND candidate_offices.race_label ~~ '%副總統%'::text AND candidate_offices.person_position_label ~~ '%總統%'::text THEN '總統'::text
                    WHEN candidate_offices.race_label ~~ '%總統%'::text AND candidate_offices.person_position_label ~~ '%副總統%'::text THEN candidate_offices.person_position_label
                    ELSE COALESCE(candidate_offices.race_label, candidate_offices.person_position_label)
                END AS current_office_label
           FROM candidate_offices
          WHERE (candidate_offices.registration_status = 'elected'::text OR candidate_offices.is_elected = true) AND NOT (EXISTS ( SELECT 1
                   FROM ended_current_offices ended
                  WHERE ended.canonical_person_id = candidate_offices.canonical_person_id AND ended.election_year = candidate_offices.election_year AND ended.race_type = candidate_offices.race_type)) AND (candidate_offices.election_year IS NULL OR COALESCE(candidate_offices.race_title, ''::text) ~ '(總統|副總統|立法委員|立委|不分區)'::text AND candidate_offices.election_year >= 2024 OR COALESCE(candidate_offices.race_title, ''::text) ~ '(市長|縣長|區長|議員|鄉長|鎮長|市民代表|鄉民代表|鎮民代表|村長|里長|代表)'::text AND candidate_offices.election_year >= 2022 OR COALESCE(candidate_offices.race_title, ''::text) !~ '(總統|副總統|立法委員|立委|不分區|市長|縣長|區長|議員|鄉長|鎮長|市民代表|鄉民代表|鎮民代表|村長|里長|代表)'::text AND candidate_offices.election_year >= 2024)
          ORDER BY candidate_offices.canonical_person_id, (
                CASE
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~~ '%副總統%'::text THEN 1
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~~ '%總統%'::text THEN 0
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~ '(立法委員|立委)'::text THEN 2
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~ '(市長|縣長)'::text THEN 3
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~~ '%議員%'::text THEN 5
                    ELSE 8
                END), candidate_offices.election_year DESC NULLS LAST, candidate_offices.updated_at DESC
        ), official_current_offices AS (
         SELECT DISTINCT ON (person_map.canonical_person_id) person_map.canonical_person_id,
            source_person."position" AS current_office_label
           FROM source_people source_person
             JOIN person_identity_matches identity_match ON identity_match.source_person_id = source_person.id AND (identity_match.match_status = ANY (ARRAY['auto_matched'::text, 'probable_match'::text]))
             JOIN person_canonical_map person_map ON person_map.person_id = identity_match.person_id
          WHERE source_person.source_type = 'official_officeholder'::text AND source_person.is_public = true AND (source_person.source_payload ->> 'isCurrent'::text) = 'true'::text AND NULLIF(btrim(source_person."position"), ''::text) IS NOT NULL AND source_person."position" !~ '(候選人|參選|擬參選)'::text
          ORDER BY person_map.canonical_person_id, (
                CASE
                    WHEN source_person."position" ~~ '%立法院院長%'::text AND source_person."position" !~~ '%副院長%'::text THEN 0
                    WHEN source_person."position" ~~ '%立法院副院長%'::text THEN 1
                    WHEN source_person."position" ~~ '%立法委員%'::text THEN 2
                    ELSE 5
                END), source_person.election_year DESC NULLS LAST, source_person.updated_at DESC
        ), upcoming_candidates AS (
         SELECT DISTINCT ON (candidate_offices.canonical_person_id) candidate_offices.canonical_person_id,
                CASE
                    WHEN candidate_offices.race_label ~~ '%總統%'::text AND candidate_offices.race_label ~~ '%副總統%'::text AND candidate_offices.person_position_label ~~ '%副總統%'::text THEN '副總統'::text
                    WHEN candidate_offices.race_label ~~ '%總統%'::text AND candidate_offices.race_label ~~ '%副總統%'::text AND candidate_offices.person_position_label ~~ '%總統%'::text THEN '總統'::text
                    WHEN candidate_offices.race_label ~~ '%總統%'::text AND candidate_offices.person_position_label ~~ '%副總統%'::text THEN candidate_offices.person_position_label
                    ELSE COALESCE(candidate_offices.race_label, candidate_offices.person_position_label)
                END AS upcoming_candidate_label
           FROM candidate_offices
          WHERE ((candidate_offices.candidacy_status = ANY (ARRAY['party_nominee'::text, 'officially_announced'::text, 'registered'::text, 'qualified'::text])) OR (candidate_offices.registration_status = ANY (ARRAY['pending'::text, 'registered'::text, 'qualified'::text]))) AND candidate_offices.election_year >= EXTRACT(year FROM CURRENT_DATE)::integer
          ORDER BY candidate_offices.canonical_person_id, candidate_offices.election_year, (
                CASE
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~~ '%副總統%'::text THEN 1
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~~ '%總統%'::text THEN 0
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~ '(立法委員|立委)'::text THEN 2
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~ '(市長|縣長)'::text THEN 3
                    WHEN COALESCE(candidate_offices.race_label, candidate_offices.person_position_label, ''::text) ~~ '%議員%'::text THEN 5
                    ELSE 8
                END), candidate_offices.updated_at DESC
        )
 SELECT canonical.id AS person_id,
    canonical.name,
    COALESCE(canonical.alias, (array_remove(array_agg(mapped.alias ORDER BY mapped.updated_at DESC), NULL::text))[1]) AS alias,
    COALESCE(canonical.party, (array_remove(array_agg(mapped.party ORDER BY mapped.updated_at DESC), NULL::text))[1]) AS party,
    COALESCE(official_current_offices.current_office_label, current_offices.current_office_label,
        CASE
            WHEN canonical."position" !~ '(候選人|參選|擬參選)'::text THEN canonical."position"
            ELSE NULL::text
        END, (array_remove(array_agg(mapped."position" ORDER BY mapped.updated_at DESC) FILTER (WHERE mapped."position" !~ '(候選人|參選|擬參選)'::text), NULL::text))[1]) AS "position",
    COALESCE(canonical.election_year, (array_remove(array_agg(mapped.election_year ORDER BY mapped.updated_at DESC), NULL::integer))[1]) AS election_year,
    COALESCE(canonical.district, (array_remove(array_agg(mapped.district ORDER BY mapped.updated_at DESC), NULL::text))[1]) AS district,
    max(mapped.updated_at) AS updated_at,
    photo.photo_url AS primary_photo_url,
    photo.thumbnail_url AS primary_photo_thumbnail_url,
    photo.source_name AS photo_source_name,
    photo.source_url AS photo_source_url,
    photo.license_type AS photo_license_type,
    photo.license_url AS photo_license_url,
    photo.attribution AS photo_attribution,
    COALESCE(NULLIF(canonical.gender, 'unknown'::text), (array_remove(array_agg(NULLIF(mapped.gender, 'unknown'::text) ORDER BY mapped.updated_at DESC), NULL::text))[1], canonical.gender) AS gender,
    max(official_profile.education) AS education,
    max(official_profile.experience) AS experience,
    COALESCE(official_current_offices.current_office_label, current_offices.current_office_label) AS current_office_label,
    upcoming_candidates.upcoming_candidate_label
   FROM mapped_people mapped
     JOIN canonical_people canonical ON canonical.id = mapped.canonical_person_id
     LEFT JOIN public.official_profile_values official_profile ON official_profile.person_id = canonical.id
     LEFT JOIN public_person_primary_photos photo ON photo.person_id = canonical.id
     LEFT JOIN official_current_offices ON official_current_offices.canonical_person_id = canonical.id
     LEFT JOIN current_offices ON current_offices.canonical_person_id = canonical.id
     LEFT JOIN upcoming_candidates ON upcoming_candidates.canonical_person_id = canonical.id
  GROUP BY canonical.id, canonical.name, canonical.alias, canonical.party, canonical."position", canonical.election_year, canonical.district, canonical.gender, canonical.education, canonical.experience, photo.photo_url, photo.thumbnail_url, photo.source_name, photo.source_url, photo.license_type, photo.license_url, photo.attribution, official_current_offices.current_office_label, current_offices.current_office_label, upcoming_candidates.upcoming_candidate_label;
CREATE OR REPLACE VIEW public.public_person_claims AS
 SELECT claim.id AS claim_id,
    canonical.canonical_person_id AS person_id,
    claim.claim_type,
    claim.claim_value,
    claim.claim_json,
    claim.confidence_level,
    claim.review_score,
    claim.source_name,
    claim.source_url,
    claim.observed_at,
    claim.updated_at,
    claim.candidate_id
   FROM person_claims claim
     JOIN person_canonical_map canonical ON canonical.person_id = claim.person_id
     JOIN people person ON person.id = canonical.canonical_person_id AND person.is_public = true
  WHERE claim.review_status = 'verified'::text AND claim.visibility = 'public'::text AND claim.is_public = true AND public.official_profile_claim_allowed(claim.claim_type,claim.claim_value,claim.claim_json,claim.person_id,claim.source_url)
 AND (claim.claim_type<>'birth_date' OR NOT EXISTS(SELECT 1 FROM public.official_profile_values profile WHERE profile.person_id=canonical.canonical_person_id AND profile.birth_conflict));
CREATE OR REPLACE FUNCTION published.person_claims_for(p_person_ids uuid[])
 RETURNS TABLE(claim_id uuid, person_id uuid, claim_type text, claim_value text, claim_json jsonb, confidence_level text, review_score numeric, source_name text, source_url text, observed_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'published'
AS $function$
DECLARE
    v_person_count INTEGER;
BEGIN
    SELECT COUNT(DISTINCT input.person_id)
    INTO v_person_count
    FROM UNNEST(COALESCE(p_person_ids, ARRAY[]::UUID[])) AS input(person_id)
    WHERE input.person_id IS NOT NULL;

    IF v_person_count > 4 THEN
        RAISE EXCEPTION 'person_claims_for accepts at most 4 person ids';
    END IF;

    RETURN QUERY
    WITH RECURSIVE requested_people AS (
        SELECT DISTINCT input.person_id
        FROM UNNEST(COALESCE(p_person_ids, ARRAY[]::UUID[])) AS input(person_id)
        JOIN public.public_people_list_cached profile
          ON profile.person_id = input.person_id
        WHERE input.person_id IS NOT NULL
    ),
    member_ids(canonical_person_id, source_person_id, path, depth) AS (
        SELECT
            requested.person_id,
            requested.person_id,
            ARRAY[requested.person_id],
            0
        FROM requested_people requested

        UNION ALL

        SELECT
            member.canonical_person_id,
            decision.duplicate_person_id,
            member.path || decision.duplicate_person_id,
            member.depth + 1
        FROM member_ids member
        JOIN public.person_merge_decisions decision
          ON decision.canonical_person_id = member.source_person_id
         AND decision.status = 'verified'
        WHERE member.depth < 20
          AND NOT decision.duplicate_person_id = ANY(member.path)
    )
    SELECT
        claim.id,
        member.canonical_person_id,
        claim.claim_type,
        claim.claim_value,
        claim.claim_json,
        claim.confidence_level,
        claim.review_score,
        claim.source_name,
        claim.source_url,
        claim.observed_at,
        claim.updated_at
    FROM member_ids member
    JOIN public.people canonical
      ON canonical.id = member.canonical_person_id
     AND canonical.is_public
    JOIN public.person_claims claim
      ON claim.person_id = member.source_person_id
    WHERE claim.review_status = 'verified'
      AND claim.visibility = 'public'
      AND claim.is_public
      AND public.official_profile_claim_allowed(claim.claim_type,claim.claim_value,claim.claim_json,claim.person_id,claim.source_url)
      AND (claim.claim_type<>'birth_date' OR NOT EXISTS(SELECT 1 FROM public.official_profile_values profile WHERE profile.person_id=member.canonical_person_id AND profile.birth_conflict))
    ORDER BY
        member.canonical_person_id,
        claim.observed_at DESC NULLS LAST,
        claim.id
    LIMIT 401;
END;
$function$
;

ALTER TABLE published.person_demographics ALTER COLUMN birth_date DROP NOT NULL;

CREATE OR REPLACE FUNCTION published.refresh_person_demographics()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
BEGIN
 -- Clear stale derived dates, including people whose remaining source has partial precision or conflicts.
 UPDATE published.person_demographics d SET birth_date=NULL,updated_at=now()
 WHERE d.birth_date IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM public.official_profile_values p WHERE p.person_id=d.person_id
  AND p.birth_value ~ '^\d{4}-\d{2}-\d{2}$' AND pg_input_is_valid(p.birth_value,'date')
  AND p.birth_value::date=d.birth_date);
 INSERT INTO published.person_demographics(person_id,birth_date,observed_at)
 SELECT p.person_id,p.birth_value::date,CURRENT_DATE FROM public.official_profile_values p
 JOIN public.people raw ON raw.id=p.person_id AND raw.is_public
 WHERE p.birth_value ~ '^\d{4}-\d{2}-\d{2}$' AND pg_input_is_valid(p.birth_value,'date')
 ON CONFLICT(person_id) DO UPDATE SET birth_date=excluded.birth_date,observed_at=excluded.observed_at,updated_at=now();
END $f$;

CREATE OR REPLACE FUNCTION public.guard_official_demographics()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE v text;
BEGIN
 SELECT p.birth_value INTO v FROM public.official_profile_values p WHERE p.person_id=NEW.person_id;
 NEW.birth_date:=CASE WHEN v ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND pg_input_is_valid(v,'date') THEN v::date END;
 RETURN NEW;
END $f$;
REVOKE ALL ON FUNCTION public.guard_official_demographics() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS guard_official_demographics ON published.person_demographics;
CREATE TRIGGER guard_official_demographics BEFORE INSERT OR UPDATE OF birth_date ON published.person_demographics
FOR EACH ROW EXECUTE FUNCTION public.guard_official_demographics();

CREATE OR REPLACE FUNCTION public.sync_official_profile_demographics()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE v_id uuid;
BEGIN
 IF TG_OP='INSERT' AND NEW.claim_type<>'birth_date' THEN RETURN NULL; END IF;
 IF TG_OP='DELETE' AND OLD.claim_type<>'birth_date' THEN RETURN NULL; END IF;
 IF TG_OP='UPDATE' AND NEW.claim_type<>'birth_date' AND OLD.claim_type<>'birth_date' THEN RETURN NULL; END IF;
 FOR v_id IN SELECT DISTINCT m.canonical_person_id FROM public.person_canonical_map m
 WHERE m.person_id=ANY(ARRAY[CASE WHEN TG_OP<>'INSERT' THEN OLD.person_id END,CASE WHEN TG_OP<>'DELETE' THEN NEW.person_id END]) LOOP
  INSERT INTO published.person_demographics(person_id,birth_date,observed_at)
  VALUES(v_id,NULL,CURRENT_DATE)
  ON CONFLICT(person_id) DO UPDATE SET birth_date=NULL,updated_at=now();
 END LOOP;
 RETURN NULL;
END $f$;
REVOKE ALL ON FUNCTION public.sync_official_profile_demographics() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS sync_official_profile_demographics ON public.person_claims;
CREATE TRIGGER sync_official_profile_demographics AFTER INSERT OR UPDATE OR DELETE ON public.person_claims
FOR EACH ROW EXECUTE FUNCTION public.sync_official_profile_demographics();

CREATE OR REPLACE VIEW published.home_candidate_summaries AS
 SELECT candidate.candidate_id,
    candidate.person_id,
    candidate.person_name,
    candidate.person_party,
    candidate.person_position,
    candidate.race_id,
    candidate.race_title,
    candidate.election_id,
    candidate.election_name,
    candidate.region_id,
    candidate.region_name,
    candidate.party,
    candidate.candidate_no,
    candidate.registration_status,
    candidate.vote_count,
    candidate.vote_rate,
    candidate.is_elected,
    candidate.is_incumbent,
    candidate.election_year,
    candidate.candidacy_status,
    candidate.election_result,
    candidate.status_updated_at,
    candidate.candidate_updated_at,
    candidate.source_name,
    candidate.source_url,
    candidate.primary_photo_url,
    candidate.primary_photo_thumbnail_url,
    candidate.photo_attribution,
    candidate.photo_license_type,
    person.gender,
    birth_date.birth_value AS birth_date
   FROM published.candidates candidate
     LEFT JOIN published.people_directory person ON person.person_id = candidate.person_id
     LEFT JOIN public.official_profile_values birth_date ON birth_date.person_id=candidate.person_id;
CREATE OR REPLACE VIEW public.person_duplicate_review_queue AS
 WITH verified_birth_dates AS (
 SELECT m.person_id,v.birth_value,v.birth_conflict,CASE WHEN NOT v.birth_conflict AND v.birth_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN v.birth_value END AS birth_date
 FROM public.person_canonical_map m JOIN public.official_profile_values v ON v.person_id=m.canonical_person_id

        ), public_people_base AS (
         SELECT p.id,
            p.name,
            p.party,
            p."position",
            p.district,
            p.gender,
            birth_dates.birth_date,birth_dates.birth_value,birth_dates.birth_conflict,
            p.education,
            p.experience,
            p.updated_at,
            lower(regexp_replace(replace(p.name, '臺'::text, '台'::text), '\s+'::text, ''::text, 'g'::text)) AS normalized_name,
            lower(regexp_replace(replace(COALESCE(NULLIF(p.party, ''::text), '未知政黨'::text), '臺'::text, '台'::text), '\s+'::text, ''::text, 'g'::text)) AS normalized_party,
            lower(regexp_replace(replace(COALESCE(NULLIF(p.district, ''::text), '未知選區'::text), '臺'::text, '台'::text), '\s+'::text, ''::text, 'g'::text)) AS normalized_district,
                CASE
                    WHEN p."position" IS NOT NULL THEN 1
                    ELSE 0
                END +
                CASE
                    WHEN p.district IS NOT NULL THEN 1
                    ELSE 0
                END +
                CASE
                    WHEN p.gender IS NOT NULL AND p.gender <> 'unknown'::text THEN 1
                    ELSE 0
                END +
                CASE
                    WHEN p.education IS NOT NULL THEN 1
                    ELSE 0
                END +
                CASE
                    WHEN p.experience IS NOT NULL THEN 1
                    ELSE 0
                END AS profile_score
           FROM people p
             LEFT JOIN verified_birth_dates birth_dates ON birth_dates.person_id = p.id
          WHERE p.is_public = true
        ), verified_external_ids AS (
         SELECT DISTINCT pc.person_id,pc.claim_value AS external_id
           FROM person_claims pc
          WHERE pc.claim_type = 'external_id'::text AND pc.review_status = 'verified'::text AND pc.visibility = 'public'::text AND pc.is_public = true AND pc.claim_value IS NOT NULL AND pc.claim_value ~ '^wikidata:Q[0-9]+$'
 AND pc.claim_json->'stablePersonIdReview'->>'status'='verified'
 AND pc.claim_json->'stablePersonIdReview'->>'independentEvidence'='true'
 AND NULLIF(pc.claim_json->'stablePersonIdReview'->>'evidenceUrl','') IS NOT NULL
        ), pair_candidates AS (
         SELECT LEAST(left_ids.person_id, right_ids.person_id) AS left_person_id,
            GREATEST(left_ids.person_id, right_ids.person_id) AS right_person_id,
            'same verified external ID'::text AS reason,
            'A'::text AS confidence_level,
            100::numeric AS score,
            jsonb_build_object('externalId', left_ids.external_id) AS evidence_json
           FROM verified_external_ids left_ids
             JOIN verified_external_ids right_ids ON right_ids.external_id = left_ids.external_id AND right_ids.person_id > left_ids.person_id
             JOIN public_people_base left_person ON left_person.id = left_ids.person_id
             JOIN public_people_base right_person ON right_person.id = right_ids.person_id
          WHERE NOT COALESCE(left_person.birth_conflict,false) AND NOT COALESCE(right_person.birth_conflict,false)
 AND (left_person.birth_value IS NULL OR right_person.birth_value IS NULL OR left(left_person.birth_value,least(length(left_person.birth_value),length(right_person.birth_value)))=left(right_person.birth_value,least(length(left_person.birth_value),length(right_person.birth_value))))
 AND NOT EXISTS(SELECT 1 FROM verified_external_ids other WHERE other.person_id IN (left_ids.person_id,right_ids.person_id) AND other.external_id<>left_ids.external_id)
 AND NOT (left_person.birth_date IS NOT NULL AND right_person.birth_date IS NOT NULL AND left_person.birth_date <> right_person.birth_date) AND NOT (left_person.gender IS NOT NULL AND right_person.gender IS NOT NULL AND left_person.gender <> 'unknown'::text AND right_person.gender <> 'unknown'::text AND left_person.gender <> right_person.gender)
        UNION ALL
         SELECT LEAST(left_person.id, right_person.id) AS left_person_id,
            GREATEST(left_person.id, right_person.id) AS right_person_id,
            'same normalized name, gender, and birth date without shared external ID'::text AS reason,
            'B'::text AS confidence_level,
            85::numeric AS score,
            jsonb_build_object('normalizedName', left_person.normalized_name, 'gender', left_person.gender, 'birthDate', left_person.birth_date, 'note', 'strong candidate, but not A-level without a shared verified external ID') AS evidence_json
           FROM public_people_base left_person
             JOIN public_people_base right_person ON right_person.normalized_name = left_person.normalized_name AND right_person.gender = left_person.gender AND right_person.birth_date = left_person.birth_date AND right_person.id > left_person.id
          WHERE left_person.gender IS NOT NULL AND left_person.gender <> 'unknown'::text AND left_person.birth_date IS NOT NULL
        ), deduped_pairs AS (
         SELECT DISTINCT ON (pair_candidates.left_person_id, pair_candidates.right_person_id) pair_candidates.left_person_id,
            pair_candidates.right_person_id,
            pair_candidates.reason,
            pair_candidates.confidence_level,
            pair_candidates.score,
            pair_candidates.evidence_json
           FROM pair_candidates
          ORDER BY pair_candidates.left_person_id, pair_candidates.right_person_id, pair_candidates.score DESC
        ), ranked_pairs AS (
         SELECT pair.left_person_id,
            pair.right_person_id,
            pair.reason,
            pair.confidence_level,
            pair.score,
            pair.evidence_json,
            left_person.profile_score AS left_score,
            right_person.profile_score AS right_score,
                CASE
                    WHEN right_person.profile_score > left_person.profile_score THEN right_person.id
                    ELSE left_person.id
                END AS suggested_canonical_person_id,
                CASE
                    WHEN right_person.profile_score > left_person.profile_score THEN left_person.id
                    ELSE right_person.id
                END AS suggested_duplicate_person_id
           FROM deduped_pairs pair
             JOIN public_people_base left_person ON left_person.id = pair.left_person_id
             JOIN public_people_base right_person ON right_person.id = pair.right_person_id
        )
 SELECT ranked_pairs.suggested_duplicate_person_id AS duplicate_person_id,
    duplicate_person.name AS duplicate_person_name,
    duplicate_person.party AS duplicate_person_party,
    duplicate_person."position" AS duplicate_person_position,
    duplicate_person.district AS duplicate_person_district,
    ranked_pairs.suggested_canonical_person_id AS canonical_person_id,
    canonical_person.name AS canonical_person_name,
    canonical_person.party AS canonical_person_party,
    canonical_person."position" AS canonical_person_position,
    canonical_person.district AS canonical_person_district,
    ranked_pairs.reason,
    ranked_pairs.confidence_level,
    ranked_pairs.score,
    ranked_pairs.evidence_json
   FROM ranked_pairs
     JOIN public_people_base duplicate_person ON duplicate_person.id = ranked_pairs.suggested_duplicate_person_id
     JOIN public_people_base canonical_person ON canonical_person.id = ranked_pairs.suggested_canonical_person_id
  WHERE NOT (EXISTS ( SELECT 1
           FROM person_merge_decisions decision
          WHERE (decision.status = ANY (ARRAY['verified'::text, 'rejected'::text, 'archived'::text])) AND (decision.duplicate_person_id = ranked_pairs.suggested_duplicate_person_id AND decision.canonical_person_id = ranked_pairs.suggested_canonical_person_id OR decision.duplicate_person_id = ranked_pairs.suggested_canonical_person_id AND decision.canonical_person_id = ranked_pairs.suggested_duplicate_person_id))) AND NOT (EXISTS ( SELECT 1
           FROM person_merge_decisions verified_decision
          WHERE verified_decision.status = 'verified'::text AND verified_decision.duplicate_person_id = ranked_pairs.suggested_duplicate_person_id)) AND NOT (EXISTS ( SELECT 1
           FROM person_canonical_map duplicate_map
             JOIN person_canonical_map canonical_map ON canonical_map.person_id = ranked_pairs.suggested_canonical_person_id AND canonical_map.canonical_person_id = duplicate_map.canonical_person_id
          WHERE duplicate_map.person_id = ranked_pairs.suggested_duplicate_person_id))
  ORDER BY ranked_pairs.score DESC, duplicate_person.name, canonical_person.name;

-- Preserve released office/status logic; only education/experience use official values.
CREATE OR REPLACE VIEW published.people AS
SELECT person.person_id,
    person.name,
    person.alias,
    person.party,
    person."position",
    person.election_year,
    person.district,
    person.updated_at,
    person.primary_photo_url,
    person.primary_photo_thumbnail_url,
    person.photo_source_name,
    person.photo_source_url,
    person.photo_license_type,
    person.photo_license_url,
    person.photo_attribution,
    person.gender,
    official_profile.education,
    official_profile.experience,
    person.current_office_label,
    person.upcoming_candidate_label,
    person.list_role,
    person.list_status,
    person.list_is_grassroots,
    person.list_status_order,
    person.list_role_order,
    (EXISTS ( SELECT 1
           FROM person_party_affiliations affiliation
          WHERE affiliation.person_id = person.person_id AND affiliation.role_context = 'party_officer'::text AND affiliation.is_current = true AND affiliation.is_public = true AND affiliation.review_status = 'verified'::text)) AND person.current_office_label IS NULL AND person.upcoming_candidate_label IS NULL AND summary.person_id IS NULL AS list_is_party_only,
    COALESCE(summary.candidate_count, 0::bigint) AS candidate_count,
        CASE
            WHEN latest.candidate_id IS NULL THEN NULL::jsonb
            ELSE jsonb_strip_nulls(jsonb_build_object('candidateId', latest.candidate_id, 'raceId', latest.race_id, 'raceTitle', latest.race_title, 'electionId', latest.election_id, 'electionName', latest.election_name, 'electionYear', latest.election_year, 'party', latest.party, 'candidateNo', latest.candidate_no, 'registrationStatus', latest.registration_status, 'candidacyStatus', latest.candidacy_status, 'electionResult', latest.election_result, 'isElected', latest.is_elected))
        END AS latest_candidacy,
    summary.primary_region_id,
    latest.region_name AS primary_region_name,
    region.slug AS primary_region_slug,
    summary.published_at
   FROM public_people_list_cached person
     LEFT JOIN public.official_profile_values official_profile ON official_profile.person_id = person.person_id
     LEFT JOIN published.person_candidate_summaries summary ON summary.person_id = person.person_id
     LEFT JOIN published.candidate_facts latest ON latest.candidate_id = summary.latest_candidate_id
     LEFT JOIN published.regions region ON region.region_id = summary.primary_region_id;

-- The shared cache entry point must always replace stale demographic projections too.
CREATE OR REPLACE FUNCTION public.refresh_public_people_list_cached()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
BEGIN
 REFRESH MATERIALIZED VIEW public.public_people_list_cached;
 PERFORM published.refresh_person_demographics();
END $f$;

-- One refresh per modifying statement; never one refresh per claim row.
-- Keeps legacy cache consumers consistent with the claim and raw-person projections.
CREATE OR REPLACE FUNCTION public.refresh_official_profile_cache_statement()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
DECLARE touched boolean:=false;
BEGIN
 IF TG_OP='INSERT' THEN
  SELECT EXISTS(SELECT 1 FROM new_claims WHERE claim_type IN ('birth_date','education','experience')) INTO touched;
 ELSIF TG_OP='DELETE' THEN
  SELECT EXISTS(SELECT 1 FROM old_claims WHERE claim_type IN ('birth_date','education','experience')) INTO touched;
 ELSE
  SELECT EXISTS(SELECT 1 FROM new_claims n JOIN old_claims o USING(id)
   WHERE (n.claim_type IN ('birth_date','education','experience') OR o.claim_type IN ('birth_date','education','experience'))
   AND ROW(n.person_id,n.claim_type,n.claim_value,n.source_url,n.review_status,n.visibility,n.is_public,n.claim_json->'officialProfilePolicy')
    IS DISTINCT FROM ROW(o.person_id,o.claim_type,o.claim_value,o.source_url,o.review_status,o.visibility,o.is_public,o.claim_json->'officialProfilePolicy')) INTO touched;
 END IF;
 IF touched THEN REFRESH MATERIALIZED VIEW public.public_people_list_cached; END IF;
 RETURN NULL;
END $f$;
REVOKE ALL ON FUNCTION public.refresh_official_profile_cache_statement() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS official_profile_cache_insert ON public.person_claims;
DROP TRIGGER IF EXISTS official_profile_cache_update ON public.person_claims;
DROP TRIGGER IF EXISTS official_profile_cache_delete ON public.person_claims;
CREATE TRIGGER official_profile_cache_insert AFTER INSERT ON public.person_claims REFERENCING NEW TABLE AS new_claims FOR EACH STATEMENT EXECUTE FUNCTION public.refresh_official_profile_cache_statement();
CREATE TRIGGER official_profile_cache_update AFTER UPDATE ON public.person_claims REFERENCING OLD TABLE AS old_claims NEW TABLE AS new_claims FOR EACH STATEMENT EXECUTE FUNCTION public.refresh_official_profile_cache_statement();
CREATE TRIGGER official_profile_cache_delete AFTER DELETE ON public.person_claims REFERENCING OLD TABLE AS old_claims FOR EACH STATEMENT EXECUTE FUNCTION public.refresh_official_profile_cache_statement();

SELECT public.refresh_public_people_list_cached();
-- These two snapshots contain no resumes, but refresh the already-supported directory projection.
DO $directory_refresh$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='published' AND c.relname='people_directory_snapshot' AND c.relkind='m') THEN
  REFRESH MATERIALIZED VIEW published.people_directory_snapshot;
 ELSIF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='published' AND c.relname='people_directory' AND c.relkind='m') THEN
  REFRESH MATERIALIZED VIEW published.people_directory;
 ELSE
  RAISE EXCEPTION 'Expected published people directory materialized view is missing';
 END IF;
END $directory_refresh$;
NOTIFY pgrst,'reload schema';
COMMIT;
